fn diag_val(i: isize, j: isize) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut matrix = Vec::with_capacity(n);
    for row in 0..n {
        let mut current_row = Vec::with_capacity(n);
        for col in 0..n {
            // Convert usize indices to isize for diag_val
            current_row.push(diag_val(row as isize, col as isize));
        }
        matrix.push(current_row);
    }
    matrix
}

fn main() {
    let mat = identity(4);
    for row in mat {
        println!("{:?}", row);
    }
}